def addbmm_backward(
    grad_output,
    batch1,
    batch2,
    beta=1.0,
    alpha=1.0,
    needs_input_grad=(True, True, True),
):
    logger.debug("GEMS ADDBMM_BACKWARD")
    if grad_output.device != batch1.device or grad_output.device != batch2.device:
        raise ValueError("addbmm_backward inputs must be on one device")
    if grad_output.dtype != batch1.dtype or grad_output.dtype != batch2.dtype:
        raise ValueError("addbmm_backward inputs must have the same dtype")

    B, M, K = batch1.shape
    B2, K2, N = batch2.shape
    if B != B2 or K != K2 or grad_output.shape != (M, N):
        raise ValueError("addbmm_backward input shapes are incompatible")

    need_bias, need_batch1, need_batch2 = needs_input_grad
    grad_output = grad_output.contiguous()
    batch1 = batch1.contiguous()
    batch2 = batch2.contiguous()
    grad_bias = torch.empty_like(grad_output) if need_bias else None
    grad_batch1 = torch.empty_like(batch1) if need_batch1 else None
    grad_batch2 = torch.empty_like(batch2) if need_batch2 else None
    if not any(needs_input_grad):
        return grad_bias, grad_batch1, grad_batch2

    dummy = grad_output

    def grid(meta):
        bias_tiles = (
            triton.cdiv(M, meta["BLOCK_SIZE_M"]) * triton.cdiv(N, meta["BLOCK_SIZE_N"])
            if need_bias
            else 0
        )
        batch1_tiles = (
            B
            * triton.cdiv(M, meta["BLOCK_SIZE_M"])
            * triton.cdiv(K, meta["BLOCK_SIZE_K"])
            if need_batch1
            else 0
        )
        batch2_tiles = (
            B
            * triton.cdiv(K, meta["BLOCK_SIZE_K"])
            * triton.cdiv(N, meta["BLOCK_SIZE_N"])
            if need_batch2
            else 0
        )
        return (bias_tiles + batch1_tiles + batch2_tiles,)

    total_output_elements = (
        (grad_output.numel() if need_bias else 0)
        + (batch1.numel() if need_batch1 else 0)
        + (batch2.numel() if need_batch2 else 0)
    )
    if total_output_elements == 0:
        return grad_bias, grad_batch1, grad_batch2

    with torch_device_fn.device(grad_output.device):
        addbmm_backward_kernel[grid](
            grad_output,
            batch1,
            batch2,
            grad_bias if need_bias else dummy,
            grad_batch1 if need_batch1 else dummy,
            grad_batch2 if need_batch2 else dummy,
            alpha,
            beta,
            B,
            M,
            N,
            K,
            NEED_BIAS=need_bias,
            NEED_BATCH1=need_batch1,
            NEED_BATCH2=need_batch2,
            IS_FP64=grad_output.dtype == torch.float64,
        )
    return grad_bias, grad_batch1, grad_batch2


class AddbmmFunction(torch.autograd.Function):
    @staticmethod
    def forward(ctx, bias, batch1, batch2, beta, alpha):
        batch1 = batch1.contiguous()
        batch2 = batch2.contiguous()
        ctx.save_for_backward(batch1, batch2)
        ctx.beta = beta
        ctx.alpha = alpha
        return _addbmm_impl(bias, batch1, batch2, beta=beta, alpha=alpha)

    @staticmethod
    def backward(ctx, grad_output):
        batch1, batch2 = ctx.saved_tensors
        grad_bias, grad_batch1, grad_batch2 = addbmm_backward(
            grad_output,
            batch1,
            batch2,
            beta=ctx.beta,
            alpha=ctx.alpha,
            needs_input_grad=ctx.needs_input_grad[:3],
        )
        return grad_bias, grad_batch1, grad_batch2, None, None


def _addbmm_impl(bias, batch1, batch2, beta=1.0, alpha=1.0):

    assert batch1.ndim == 3 and batch2.ndim == 3, "batch1 and batch2 must be 3D"
    assert bias.ndim == 2, "bias must be 2D"

    B, M, K = batch1.shape
    _, K2, N = batch2.shape
    assert K == K2, "Inner dimensions must match"
    assert (
        bias.shape[0] == M and bias.shape[1] == N
    ), f"bias shape mismatch: expected ({M}, {N}), got {bias.shape}"

    batch1 = batch1.contiguous()
    batch2 = batch2.contiguous()
    bias = bias.contiguous()
    out = torch.empty((M, N), dtype=bias.dtype, device=bias.device)

    grid = lambda META: (
        triton.cdiv(M, META["BLOCK_SIZE_M"]),
        triton.cdiv(N, META["BLOCK_SIZE_N"]),
    )

    with torch_device_fn.device(bias.device):
        addbmm_kernel[grid](
            bias,
            batch1,
            batch2,
            out,
            alpha,
            beta,
            B,
            M,
            N,
            K,
            bias.stride(0),
            bias.stride(1),
            batch1.stride(0),
            batch1.stride(1),
            batch1.stride(2),
            batch2.stride(0),
            batch2.stride(1),
            batch2.stride(2),
            out.stride(0),
            out.stride(1),
            IS_FP64=bias.dtype == torch.float64,
        )

    return out


def addbmm(bias, batch1, batch2, beta=1.0, alpha=1.0):
    logger.debug("GEMS ADDBMM")
    if torch.is_grad_enabled() and (
        bias.requires_grad or batch1.requires_grad or batch2.requires_grad
    ):
        return AddbmmFunction.apply(bias, batch1, batch2, beta, alpha)
    return _addbmm_impl(bias, batch1, batch2, beta=beta, alpha=alpha)


